export function adventureConfig(id){const factories={palisade:palisadeConfig,inquest:inquestConfig,shoals:shoalsConfig,theater:theaterConfig,courier:courierConfig,foundrywatch:watchConfig,foundry:foundryConfig,harbor:harborConfig,seasoned:()=>trialConfig("seasoned"),veteran:()=>trialConfig("veteran"),tutorial:tutorialConfig,chapter:chapterConfig,classic:defaults,vigil:challengeConfig,archive:()=>archiveConfig(true),scarcity:()=>scarcityConfig(true),survival:()=>survivalConfig('formation'),hospice:()=>hospiceConfig('source')};if(!factories[id])throw Error('未知冒险');return factories[id]();}
export function chapterEnding(report){if(report.config.expedition==='palisade')return {title:report.won?'哨声渐息，双盾墙已露出缺口。':'哨声未停，队伍先退回栈桥外。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。援护来源倒下不能撤销既有检定，也不会退还已经支付的材料；正常通关结算可领取固定哨誓披甲。`,won:report.won};if(report.config.expedition==='inquest')return {title:report.won?'追问渐息，自己的心声仍然清楚。':'回声尚未散去，队伍先退出问堂。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。诘心回声不附着负面状态，净化不能撤销已经造成的心理伤害；正常结算可获得定心缎带。`,won:report.won};if(report.config.expedition==='shoals')return {title:report.won?'新的礁线，已能画进归航海图。':'这一段礁线，仍需重新准备。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。海图编号 ${report.config.shoalsChart||1}；正常领取通关结算后记入勘探册，每图不额外发放首通奖励。`,won:report.won};if(report.config.expedition==='theater')return {title:report.won?'合唱停下，队伍带着自己的声音归来。':'旧曲仍在回响，队伍先退回门厅。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。所有削弱与净化按战报结算，奖励须回营领取。`,won:report.won};if(report.config.expedition==='courier'){const crew=report.party.filter(u=>!u.owner&&report.config.heroes.some(h=>h.id===u.id)),standing=crew.filter(u=>u.hp>0),down=crew.filter(u=>u.hp<=0);return {title:report.won?(down.length?'船已靠岸，回信由同伴代交。':'信与同伴，一起抵岸。'):'邮路尚未打通，回信先留在营地。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${standing.length}/${crew.length} 位同行者仍有战斗能力。${down.length?'在远征中倒下的'+down.map(u=>u.name).join('、')+'随船回营。':'六人完整交接了这趟回信。'}余量：${report.supplies.herb}药草 / ${report.supplies.rune}符纸 / ${report.supplies.arrow}箭矢。${report.won?'回邮铜铃须正常领取后分配。':'可回营领取已通过房间的收益，本次没有通关额外奖励。'}`,won:report.won};}if(report.config.expedition==='foundrywatch')return {title:report.won?'最后一班守望交出了钥印。':'守望未散，队伍先退回外港。',image:'foundry-v71.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length} 人存活。守望徽记须回营领取与分配。`,won:report.won};if(report.config.expedition==='foundry')return {title:report.won?'炉心归于沉寂，铸库重见海光。':'铸库仍在轰鸣，队伍暂退外港。',image:'foundry-v71.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/4 场；${report.party.filter(u=>u.hp>0).length} 人存活。余量：${report.supplies.herb}药草 / ${report.supplies.rune}符纸 / ${report.supplies.arrow}箭矢。装备与成长奖励请回营领取。`,won:report.won};if(!['chapter','harbor'].includes(report.config.expedition))return null;if(report.config.expedition==='harbor')return {title:report.won?'无光灯塔重新照亮盐风港。':'灯塔尚未点亮，远征队撤回海岸。',image:report.won?'harbor-seal-v41.png':'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/4 场；${report.party.filter(u=>u.hp>0).length} 人存活。路线：${report.rooms.map(r=>r.name).join(' → ')}。`,won:report.won};const alive=report.party.filter(u=>u.hp>0).length,cleared=report.rooms.filter(r=>r.won).length;return {title:report.won?(alive===6?'沉钟归于寂静，六人归航。':'沉钟归于寂静，有人未能归航。'):'远征止步，灯火仍在等待。',image:report.won?'last-lantern-v17.png':'abbey.png',text:`肃清 ${cleared}/${roomsFor(report.config).length} 场；${alive} 人存活。药草 ${report.supplies.herb}、符纸 ${report.supplies.rune}、箭矢 ${report.supplies.arrow}。`,won:report.won};}
